      "A": "Tidak mengalami perubahan sama sekali (tetap).",
      "B": "Bertambah sebesar 4%.",
      "C": "Berkurang sebesar 4%.",
      "D": "Berkurang sebesar 2%.",
      "E": "Bertambah sebesar 2%."
