      "B": "Segitiga dengan 4 titik putih.",
      "C": "Segidelapan (oktagon) dengan 5 titik hitam.",
      "D": "Lingkaran dengan 3 titik hitam.",
      "E": "Segilima dengan 4 titik hitam."
