      "C": "Bangun luar Persegi besar dan bangun dalam Bintang kecil putih.",
      "D": "Bangun luar Bintang besar dan bangun dalam Segitiga kecil hitam.",
      "E": "Dua buah persegi kecil saling bersinggungan."
