    "sumber_nama": "Peraturan Pemerintah No. 94 Tahun 2021 tentang Disiplin Pegawai Negeri Sipil | Ref: bahan_soal2/MATERI TKP/TKP Profesionalisme.pdf & PP No. 94/2021",
