    "soal": "Delapan tahun yang lalu umur Andi sama dengan enam kali umur Bayu. Jika tahun depan umur Andi tiga lebihnya dari dua kali umur Bayu. Berapa tahun umur Bayu enam tahun yang akan datang?",
